(* [comment removed for export] *)
Lemma pb_call (a cur cnt : Z) (fxq : FPState) Rq Mq mdq crq kq :
  inv Mq mdq crq kq a -> a + 1 <= pl_size n + n ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 0x36244 -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 48) ->
  getr Rq (PMK.reg 8) = Z_to_bv 64 (fb + 440) -> getr Rq (PMK.reg 9) = Z_to_bv 64 cur -> getr Rq (PMK.reg 18) = Z_to_bv 64 cnt ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 (fb + 496) -> getr Rq (PMK.reg 11) = Z_to_bv 64 (sp - 33) -> csl Rq ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, inv M2 md2 cr2 k2 (a + 1) ->
      getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 48) -> getr R2 (PMK.reg 8) = Z_to_bv 64 (fb + 440) -> getr R2 (PMK.reg 9) = Z_to_bv 64 cur ->
      getr R2 (PMK.reg 18) = Z_to_bv 64 cnt -> csl R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 0x36244 M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Rq 0x372d8 Mq mdq) K.
